<template><el-container class="records"><el-header><el-button @click="router.push('/health-home')">返回健康首页</el-button><h3>{{model?.label}}</h3></el-header><el-main><el-space><el-input v-model="search" placeholder="筛选当前页" clearable/><el-button @click="load">刷新</el-button><el-button @click="exportPage">导出当前页</el-button><el-button v-if="canCreate" type="primary" @click="open()">新增</el-button></el-space><el-table :data="filtered" stripe empty-text="暂无记录"><el-table-column v-for="field in columns" :key="field[0]" :prop="field[0]" :label="labels[field[0]]||field[0]" min-width="130" show-overflow-tooltip/><el-table-column label="操作" width="100"><template #default="s"><el-button link @click="open(s.row)">{{canCreate?'查看 / 编辑':'查看'}}</el-button></template></el-table-column></el-table><el-pagination v-model:current-page="page" :total="total" :page-size="10" @current-change="load"/></el-main><el-dialog v-model="dialog" :title="model?.label" width="650px"><el-form label-position="top"><el-form-item v-for="f in editableFields" :key="f[0]" :label="labels[f[0]]||f[0]"><el-input v-model="draft[f[0]]" :type="['content','notes','summary'].includes(f[0])?'textarea':'text'" :disabled="!canCreate"/></el-form-item></el-form><template #footer><el-button @click="dialog=false">关闭</el-button><el-button v-if="canCreate" type="primary" @click="save">保存</el-button></template></el-dialog></el-container></template>
<script setup>
import {ref,computed,watch,onMounted} from 'vue'
import {useRoute,useRouter} from 'vue-router'
import {call} from '@/api/health'
import models from './models.json'
import useUserStore from '@/store/modules/user'
import {ElMessage} from 'element-plus'
const route=useRoute(),router=useRouter(),rows=ref([]),total=ref(0),page=ref(1),search=ref(''),dialog=ref(false),draft=ref({})
const model=computed(()=>models.find(m=>m.module===(route.params.module||route.query.module))),columns=computed(()=>model.value?.fields||[]),editableFields=computed(()=>columns.value.filter(f=>!['id','userId'].includes(f[0]))),filtered=computed(()=>rows.value.filter(r=>JSON.stringify(r).toLowerCase().includes(search.value.toLowerCase()))),canCreate=computed(()=>model.value&&!model.value.immutable&&(['tuser','medichine'].includes(model.value.module)||useUserStore().roles.some(r=>['admin','healthadmin','healthyperson'].includes(r))))
const labels={id:'编号',userId:'用户编号',measureTime:'测量时间',deviceId:'设备编号',systolic:'收缩压',diastolic:'舒张压',heartRate:'心率',realName:'姓名',age:'年龄',heightCm:'身高 cm',weightKg:'体重 kg',phone:'电话',practitionerId:'健康师编号',title:'标题',content:'内容',source:'来源',status:'状态',reviewerId:'审核人',reviewedAt:'审核时间',medicineName:'药品名称',dosage:'用量',frequency:'频次',startDate:'开始日期',endDate:'结束日期',notes:'备注',glucose:'血糖',mealState:'餐前餐后',totalCholesterol:'总胆固醇',triglycerides:'甘油三酯',hdl:'高密度脂蛋白',ldl:'低密度脂蛋白',durationSeconds:'时长 秒',waveform:'波形',steps:'步数',deviceName:'设备名',deviceType:'设备类型',serialNumber:'序列号',visitTime:'随访时间',nextVisitTime:'下次随访'}
async function load(){if(!model.value){rows.value=[];return}const res=await call(model.value.module+'/list','get',null,{pageNum:page.value,pageSize:10,userId:route.query.userId});rows.value=res.rows;total.value=res.total}
function exportPage(){const fields=columns.value.map(f=>f[0]);const esc=x=>'"'+String(x??'').replaceAll('"','""')+'"';const csv='\ufeff'+[fields.join(','),...filtered.value.map(r=>fields.map(f=>esc(r[f])).join(','))].join('\r\n');const a=document.createElement('a');a.href=URL.createObjectURL(new Blob([csv],{type:'text/csv;charset=utf-8'}));a.download=model.value.module+'.csv';a.click();URL.revokeObjectURL(a.href)}
function open(row){draft.value=row?{...row}:{};dialog.value=true}
async function save(){const body={...draft.value};if(route.query.userId)body.userId=Number(route.query.userId);for(const [name,type] of columns.value){if(['Long','Integer','BigDecimal'].includes(type)&&body[name]!==undefined&&body[name]!=='')body[name]=Number(body[name])}await call(model.value.module,body.id?'put':'post',body);dialog.value=false;ElMessage.success('已保存');load()}
watch(()=>route.fullPath,()=>{page.value=1;load()});onMounted(load)
</script><style scoped>.records{background:#f1f7f6;min-height:100vh}.el-header{display:flex;align-items:center;gap:20px;background:white}.el-main{padding:32px}.el-table{margin:24px 0}</style>
